import{_ as o,o as a,c as i,an as t}from"./chunks/framework.DE56hfvi.js";const u=JSON.parse('{"title":"MAGEMin - C-library","description":"","frontmatter":{},"headers":[],"relativePath":"MAGEMin/MAGEMin.md","filePath":"MAGEMin/MAGEMin.md","lastUpdated":null}'),l={name:"MAGEMin/MAGEMin.md"};function n(d,e,r,s,c,m){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="MAGEMin-C-library" tabindex="-1">MAGEMin - C-library <a class="header-anchor" href="#MAGEMin-C-library" aria-label="Permalink to &quot;MAGEMin - C-library {#MAGEMin-C-library}&quot;">​</a></h1><p><code>MAGEMin</code> is an open-source parallel code written in <code>C</code> that minimizes the Gibbs free energy of multiphase and multicomponent systems. The main objective of <code>MAGEMin</code> is to provide a stable, consistent and fast phase equilibrium prediction routine.</p><p>The function receives bulk-rock composition, pressure and temperature to compute the most stable phase equilibrium. Presently, <code>MAGEMin</code> provides the thermodynamic dataset used natively in <code>THERMOCALC</code>. The thermodynamic datasets are directly translated into <code>C</code> routines and implemented without transformation of variables or coordinate systems, thus eliminating inconsistencies.</p><p>The list of all available thermodynamic datasets is presented below.</p><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>The <code>C</code> backend of <code>MAGEMin</code> is not the most user-friendly way to use <code>MAGEMin</code> toolset. We strongly encourage users to try out <code>MAGEMinApp.jl</code> and <code>MAGEMin_C.jl</code>. The only case where using the <code>C</code> backend of <code>MAGEMin</code> is possibly the best solution is when calling <code>MAGEMin</code> as an external library from a pre-existing <code>C</code> or <code>C++</code> code.</p></div><h2 id="Available-thermodynamic-databases" tabindex="-1">Available thermodynamic databases <a class="header-anchor" href="#Available-thermodynamic-databases" aria-label="Permalink to &quot;Available thermodynamic databases {#Available-thermodynamic-databases}&quot;">​</a></h2><p><code>MAGEMin</code> ships 15 thermodynamic databases - <code>mp</code>, <code>um</code>, <code>mb</code>, <code>mtl</code>, <code>ig</code>, <code>igd</code>, <code>igad</code>, <code>sb11</code>, <code>sb21</code>, <code>sb24</code>, <code>po</code>, <code>ume</code>, <code>mpe</code>, <code>mbe</code>, and <code>all</code> (a master database unifying every unique solution-phase model across mp/mb/mbe/ig/igd/igad/um/ume/mpe) - plus the DEW aqueous fluid model, available in <code>all</code> and several of the single-system databases.</p><p><strong>→ See the full <a href="./../database">Databases information</a> page</strong> for the acronym reference table, per-database chemical systems, phase/end-member listings, and the DEW aqueous fluid model section - kept in one place rather than duplicated here to avoid the two copies drifting apart.</p><p>For the command-line arguments used to select a database and configure a run (<code>--db=</code>, <code>--rg=</code>, <code>--buffer=</code>, <code>--DEW_solve_algorithm=</code>, etc.), see <a href="./tutorials">MAGEMin command-line reference</a>.</p><h2 id="References" tabindex="-1">References <a class="header-anchor" href="#References" aria-label="Permalink to &quot;References {#References}&quot;">​</a></h2><ul><li><p>Su et al. (2026). Igneous thermodynamic model (<code>igd</code> database), corrected from Tomlinson &amp; Holland (2021).</p></li><li><p>Green, ECR, Holland, TJB, Powell, R, Weller, OM, &amp; Riel, N (2025). Journal of Petrology, 66, doi: 10.1093/petrology/egae079</p></li><li><p>Weller, OM, Holland, TJB, Soderman, CR, Green, ECR, Powell, R, Beard, CD &amp; Riel, N (2024). New Thermodynamic Models for Anhydrous Alkaline-Silicate Magmatic Systems. Journal of Petrology, 65, doi: 10.1093/petrology/egae098</p></li><li><p>Holland, TJB, Green, ECR &amp; Powell, R (2022). A thermodynamic modelfor feldspars in KAlSi3O8-NaAlSi3O8-CaAl2Si2O8 for mineral equilibrium calculations. Journal of Metamorphic Geology, 40, 587-600, doi: 10.1111/jmg.12639</p></li><li><p>Tomlinson, EL &amp; Holland, TJB (2021). A Thermodynamic Model for the Subsolidus Evolution and Melting of Peridotite. Journal of Petrology,62, doi: 10.1093/petrology/egab012</p></li><li><p>Holland, TJB, Green, ECR &amp; Powell, R (2018). Melting of Peridotitesthrough to Granites: A Simple Thermodynamic Model in the System KNCFMASHTOCr. Journal of Petrology, 59, 881-900, doi: 10.1093/petrology/egy048</p></li><li><p>Green, ECR, White, RW, Diener, JFA, Powell, R, Holland, TJB &amp; Palin, RM (2016). Activity-composition relations for the calculationof partial melting equilibria in metabasic rocks. Journal of Metamorphic Geology, 34, 845-869, doi: 10.1111/jmg12211</p></li><li><p>White, RW, Powell, R, Holland, TJB, Johnson, TE &amp; Green, ECR (2014). New mineral activity-composition relations for thermodynamic calculations in metapelitic systems. Journal of Metamorphic Geology, 32, 261-286, doi: 10.1111/jmg.12071</p></li><li><p>Holland, TJB &amp; Powell, RW (2011). An improved and extended internally consistent thermodynamic dataset for phases of petrological interest, involving a new equation of state for solids. Journal of Metamorphic Geology, 29, 333-383, doi: 10.1111/j.1525-1314.2010.00923.x</p></li></ul>',11)])])}const h=o(l,[["render",n]]);export{u as __pageData,h as default};
